events.command:
python3 << 'EOF'
import csv

# Load sample annotations
sample_to_celltype = {}
with open('/tmp/sample_annotated.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        sample_to_celltype[row['sample']] = row['celltype']

# Load expression header
with open('/tmp/expr_header.txt') as f:
    header = f.readline().strip()
    expr_cols = header.split(',')

# Sample name -> column index (1-based)
sample_col_map = {}
for i, col in enumerate(expr_cols):
    if i == 0:
        continue
    sample_col_map[col] = i + 1

celltype_cols = {'CD4': [], 'CD8': [], 'CD14': [], 'CD19': []}
for sample, ct in sample_to_celltype.items():
    if ct in celltype_cols and sample in sample_col_map:
        celltype_cols[ct].append(sample_col_map[sample])

# Generate compact column specifications
# Format: comma-separated, with ranges where possible
def compact_spec(cols):
    """Generate compact column specification: 1,2,5-10,15"""
    if not cols:
        return ""
    cols = sorted(cols)
    parts = []
    start = cols[0]
    end = cols[0]
    for c in cols[1:]:
        if c == end + 1:
            end = c
        else:
            if start == end:
                parts.append(str(start))
            else:
                parts.append(f"{start}-{end}")
            start = c
            end = c
    if start == end:
        parts.append(str(start))
    else:
        parts.append(f"{start}-{end}")
    return ",".join(parts)

for ct in ['CD4', 'CD8', 'CD14', 'CD19']:
    cols = sorted(celltype_cols[ct])
    spec = "1," + compact_spec(cols)
    print(f"{ct}: {len(cols)} samples, spec length: {len(spec)}")
    print(f"  Spec: {spec[:200]}...")
    print()

# Also count lines in expression matrix
print("Counting lines in expression matrix...")
with open('/tmp/expr_header.txt') as f:
    # count newlines
    content = f.read()
    lines = content.count('\n')
    print(f"Approximate lines: {lines}")
EOF

